import{_ as a,c as e,o as s,ag as i}from"./chunks/framework.DQvKz0xt.js";const u=JSON.parse('{"title":"状态 (States) - Rive 编辑器","description":"状态机 (State Machines) 状态本质上就是可以在状态机中任意时刻播放的时间轴动画。一个状态可以简单到只是改变对象的颜色和位置，也可以复杂到混合多条时间轴动画。","frontmatter":{"title":"状态 (States) - Rive 编辑器","description":"状态机 (State Machines) 状态本质上就是可以在状态机中任意时刻播放的时间轴动画。一个状态可以简单到只是改变对象的颜色和位置，也可以复杂到混合多条时间轴动画。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 状态机, 状态"}]]},"headers":[],"relativePath":"editor/state-machine/states.md","filePath":"editor/state-machine/states.md","lastUpdated":1774838907000}'),n={name:"editor/state-machine/states.md"};function r(o,t,l,d,h,p){return s(),e("div",null,[...t[0]||(t[0]=[i('<p>状态机 (State Machines)</p><h1 id="状态-states" tabindex="-1">状态 (States) <a class="header-anchor" href="#状态-states" aria-label="Permalink to &quot;状态 (States)&quot;">​</a></h1><p>状态本质上就是可以在状态机中任意时刻播放的时间轴动画。一个状态可以简单到只是改变对象的颜色和位置，也可以复杂到混合多条时间轴动画。</p><h2 id="​-默认状态-default-states" tabindex="-1"><a href="#default-states">​</a> 默认状态 (Default States) <a class="header-anchor" href="#​-默认状态-default-states" aria-label="Permalink to &quot;[​](#default-states) 默认状态 (Default States)&quot;">​</a></h2><p>默认状态是每个状态机创建时自动添加的状态。 <img src="https://help.rive.app/images/42815967-dd47-4da1-ba8a-4fc12f64d972.webp" alt="默认状态"></p><h3 id="​-入口状态-entry-state" tabindex="-1"><a href="#entry-state">​</a> 入口状态 (Entry State) <a class="header-anchor" href="#​-入口状态-entry-state" aria-label="Permalink to &quot;[​](#entry-state) 入口状态 (Entry State)&quot;">​</a></h3><p>入口状态是状态机的起始点。默认已关联一个动画，但你可以随时更换。你也可以将多个动画连接到入口状态（例如：需要一个开关可以从&quot;开&quot;或&quot;关&quot;任一状态启动）。</p><h3 id="​-退出状态-exit-state" tabindex="-1"><a href="#exit-state">​</a> 退出状态 (Exit State) <a class="header-anchor" href="#​-退出状态-exit-state" aria-label="Permalink to &quot;[​](#exit-state) 退出状态 (Exit State)&quot;">​</a></h3><p>退出状态用于告诉状态机图层停止播放。在使用多图层时有特殊用途。</p><h3 id="​-任意状态-any-state" tabindex="-1"><a href="#any-state">​</a> 任意状态 (Any State) <a class="header-anchor" href="#​-任意状态-any-state" aria-label="Permalink to &quot;[​](#any-state) 任意状态 (Any State)&quot;">​</a></h3><p>与普通状态不同，连接到 Any State 的状态可以在状态机处于任何状态时被激活。非常适合用于&quot;随时可触发&quot;的场景，如更换角色皮肤。 <img src="https://help.rive.app/images/image_2.png" alt="使用 Any State 的评分系统"></p><h2 id="​-动画状态-animation-states" tabindex="-1"><a href="#animation-states">​</a> 动画状态 (Animation States) <a class="header-anchor" href="#​-动画状态-animation-states" aria-label="Permalink to &quot;[​](#animation-states) 动画状态 (Animation States)&quot;">​</a></h2><p>动画状态包括除默认状态外的所有状态类型。有三种动画状态：<strong>单动画 (Single Animation)</strong>、<strong>1D 混合 (1D Blend)</strong> 和 <strong>加性混合 (Additive Blend)</strong>。</p><p>你可以将动画从动画列表直接拖放到图表上来添加状态（默认创建单动画状态）。也可以右键点击图表创建空白状态。</p><h3 id="​-单动画状态" tabindex="-1"><a href="#single-animation-state">​</a> 单动画状态 <a class="header-anchor" href="#​-单动画状态" aria-label="Permalink to &quot;[​](#single-animation-state) 单动画状态&quot;">​</a></h3><p>任何时间轴都可以作为单动画状态。根据动画类型，可以是一次性播放、循环或乒乓模式。这是最常用的状态类型。</p><h3 id="​-混合状态-blend-states" tabindex="-1"><a href="#blend-states">​</a> 混合状态 (Blend States) <a class="header-anchor" href="#​-混合状态-blend-states" aria-label="Permalink to &quot;[​](#blend-states) 混合状态 (Blend States)&quot;">​</a></h3><p>混合状态可以将两条或更多时间轴动画混合在一起。常用于进度条、血条、滚动交互和动态面部绑定。</p><h4 id="​-1d-混合状态" tabindex="-1"><a href="#1d-blend-state">​</a> 1D 混合状态 <a class="header-anchor" href="#​-1d-混合状态" aria-label="Permalink to &quot;[​](#1d-blend-state) 1D 混合状态&quot;">​</a></h4><p>通过单个数字输入控制多条时间轴的混合。当数值变化时，一条动画淡入同时另一条淡出。 <img src="https://help.rive.app/images/image_5.png" alt="血条混合状态"> 配置步骤：</p><ol><li>创建多条时间轴动画（建议只关键帧少量属性）。</li><li>添加 1D Blend State 到图表。</li><li>使用下拉菜单关联数字输入。</li><li>添加时间轴并定义数值范围（如 0-100）。</li></ol><h4 id="​-加性混合状态" tabindex="-1"><a href="#additive-blend-state">​</a> 加性混合状态 <a class="header-anchor" href="#​-加性混合状态" aria-label="Permalink to &quot;[​](#additive-blend-state) 加性混合状态&quot;">​</a></h4><p>允许通过多个数字输入混合多条时间轴，适用于创建独特姿态（如面部表情）。 可选择 <strong>Blend by Value</strong>（固定混合比）或 <strong>Blend by Input</strong>（输入驱动混合）。</p><h2 id="​-其他状态选项" tabindex="-1"><a href="#additional-state-options">​</a> 其他状态选项 <a class="header-anchor" href="#​-其他状态选项" aria-label="Permalink to &quot;[​](#additional-state-options) 其他状态选项&quot;">​</a></h2><p>选中状态后可调整的选项：</p><ul><li><strong>状态类型</strong>：单动画、1D 混合或加性混合。</li><li><strong>动画</strong>：更改关联的时间轴。</li><li><strong>速度 (Speed)</strong>：正值正向播放，负值倒放。</li><li><strong>过渡</strong>：查看并禁用/启用离开该状态的过渡。</li></ul><p><a href="/docs/editor/state-machine/overview">概览 (Overview)</a><a href="/docs/editor/state-machine/inputs">输入 (Inputs)</a></p>',27)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
